//! The independent Python `fractions.Fraction` oracle for the rational kernel (RNL-CI-006).
//!
//! The fixture is generated by `tools/rational-oracle.py --write` and committed. This test never
//! invokes Python: it reads the recorded oracle results and recomputes every case through the
//! public Rust API, so the two implementations are genuinely independent at build and test time.

use lovelace_int::Int;
use lovelace_nat::Nat;
use lovelace_rational::Rat;

const FIXTURE: &str = include_str!("../../parity/rational/oracle.tsv");

fn parse_rat(text: &str) -> Rat {
    let (numerator, denominator) = text.split_once('/').expect("numerator/denominator");
    Rat::from_parts(
        Int::from_decimal(numerator).expect("a decimal numerator"),
        Nat::from_decimal(denominator).expect("a decimal denominator"),
    )
    .expect("the oracle never emits a zero denominator")
}

fn canonical_text(value: &Rat) -> String {
    format!(
        "{}/{}",
        value.numerator().to_decimal(),
        value.denominator().to_decimal()
    )
}

#[test]
fn every_recorded_fraction_oracle_case_recomputes_exactly() {
    let mut cases = 0usize;
    for (line_number, line) in FIXTURE.lines().enumerate() {
        let line = line.trim_end();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let parts: Vec<&str> = line.split('\t').collect();
        assert_eq!(
            parts.len(),
            4,
            "line {}: expected four tab-separated fields, got {line:?}",
            line_number + 1
        );
        let left = parse_rat(parts[1]);
        let right = parse_rat(parts[2]);
        let expected = parts[3];
        let context = format!(
            "line {}: {} {} {}",
            line_number + 1,
            parts[0],
            parts[1],
            parts[2]
        );

        match parts[0] {
            "add" => {
                assert_eq!(
                    canonical_text(&left.add(&right)),
                    expected,
                    "add: {context}"
                );
            }
            "sub" => {
                assert_eq!(
                    canonical_text(&left.sub(&right)),
                    expected,
                    "sub: {context}"
                );
            }
            "mul" => {
                assert_eq!(
                    canonical_text(&left.mul(&right)),
                    expected,
                    "mul: {context}"
                );
            }
            "div" => {
                let quotient = left
                    .checked_div(&right)
                    .unwrap_or_else(|error| panic!("div failed for {context}: {error}"));
                assert_eq!(canonical_text(&quotient), expected, "div: {context}");
            }
            "cmp" => {
                let actual = match left.cmp(&right) {
                    std::cmp::Ordering::Less => "-1",
                    std::cmp::Ordering::Equal => "0",
                    std::cmp::Ordering::Greater => "1",
                };
                assert_eq!(actual, expected, "cmp: {context}");
            }
            other => panic!(
                "line {}: unknown oracle operation {other:?}",
                line_number + 1
            ),
        }
        cases += 1;
    }
    assert!(
        cases >= 700,
        "the rational oracle fixture is non-vacuous: only {cases} cases ran"
    );
}

#[test]
fn the_oracle_covers_the_required_regressions() {
    // The three campaigns the specification names explicitly are present in the fixture.
    assert!(
        FIXTURE.contains("div\t1/2\t-1/4\t-2/1"),
        "the signed-division regression is in the fixture"
    );
    assert!(
        FIXTURE
            .lines()
            .any(|line| line.contains("div\t-1/2\t-1/4\t2/1")),
        "a negative/negative division is in the fixture"
    );
    let large_cases = FIXTURE
        .lines()
        .filter(|line| line.split('\t').nth(1).is_some_and(|text| text.len() > 60))
        .count();
    assert!(
        large_cases >= 20,
        "the oracle must exercise operands far outside u64 (found {large_cases})"
    );
}
